CREATE TABLE IF NOT EXISTS "AuthReferenceLookup" ( "Id" VARCHAR(100) PRIMARY KEY DEFAULT gen_random_uuid()::text, "Name" VARCHAR(100), "DisplayName" VARCHAR(100), "Type" VARCHAR(100),
CONSTRAINT "UQ_AuthReferenceLookup_Name_Type" UNIQUE ("Name", "Type") );
INSERT INTO "AuthReferenceLookup" ("Name", "DisplayName", "Type") VALUES ('TodoItemModule','TodoItem Module','Module'), ('MasterUpdate','MasterUpdate','PermissionSet'), ('AcmeProductModule','AcmeProduct Module','Module'), ('SystemDesignModule','SystemDesign Module','Module'), ('SystemManagerModule','SystemManager Module','Module'), ('OtherModule','Other Module','Module'), ('PermissionView','PermissionView','PermissionSet'), ('UserRoleUpdate','UserRoleUpdate','PermissionSet'), ('TodoListView','TodoListView','PermissionSet'), ('SystemDesign','SystemDesign','PermissionSet'), ('Field','Field','UIPermissionType'), ('TodoListModule','TodoList Module','Module'), ('RoleView','RoleView','PermissionSet'), ('AcmeProductUpdate','AcmeProductUpdate','PermissionSet'), ('SystemManager','SystemManager','PermissionSet'), ('UserCreate','UserCreate','PermissionSet'), ('AcmeProductCreate','AcmeProductCreate','PermissionSet'), ('AcmeOrderView','AcmeOrderView','PermissionSet'), ('PermissionModule','Permission Module','Module'), ('https://netauthapi.azurewebsites.net/','netauthapi-timetrack','InternalApiUrl'), ('UserUpdate','UserUpdate','PermissionSet'), ('Other','Other','PermissionSet'), ('UserModule','User Module','Module'), ('Screen','Screen','UIPermissionType'), ('AcmeProductView','AcmeProductView','PermissionSet'), ('TodoItemCreate','TodoItemCreate','PermissionSet'), ('RoleModule','Role Module','Module'), ('MasterModule','Master Module','Module'), ('TodoItemUpdate','TodoItemUpdate','PermissionSet'), ('PermissionUpdate','PermissionUpdate','PermissionSet'), ('MasterView','MasterView','PermissionSet'), ('TodoListCreate','TodoListCreate','PermissionSet'), ('MasterCreate','MasterCreate','PermissionSet'), ('AcmeOrderCreate','AcmeOrderCreate','PermissionSet'), ('UserView','UserView','PermissionSet'), ('AcmeOrderUpdate','AcmeOrderUpdate','PermissionSet'), ('Menu','Menu','UIPermissionType'), ('TodoItemView','TodoItemView','PermissionSet'), ('AcemOrderModule','AcmeOrder Module','Module'), ('TodoListUpdate','TodoListUpdate','PermissionSet') ON CONFLICT ("Name", "Type") DO NOTHING;

CREATE TABLE IF NOT EXISTS "UserPasswordHash" ( "UserId" VARCHAR(100) PRIMARY KEY,
"PasswordHash" VARCHAR(200), "UpdatedBy" VARCHAR(200), "UpdatedDateTime" TIMESTAMP, "UpdateReason" VARCHAR(200),
-- Foreign key (recommended, since UserId maps to User table) CONSTRAINT "FK_UserPasswordHash_User" FOREIGN KEY ("UserId") REFERENCES "User"("Id") );
INSERT INTO "UserPasswordHash" ( "UserId", "PasswordHash", "UpdatedBy", "UpdatedDateTime", "UpdateReason" ) SELECT u."Id", v."PasswordHash", NULL, NOW(), 'Initial BCrypt password' FROM ( VALUES ('test_Admin_User@systemdesign.com','$2a$11$LzB1OPiO/FoyQ8IPlXKND.IzDmSloCb5IZZ7LcCCD55U36fWIfgAO'), ('test_Level_1_User@systemdesign.com','$2a$11$8VhImHUy.k9ekQ.Jao3S6Oy3ZavD726tq8/Cyy.RsiDTuCLThH5nS'), ('test_Level_2_User@systemdesign.com','$2a$11$CCFTX7LQ54m.RQ5IvlnCPuQOIhULF95IBvwEMB45WmGiGJQ6YCB56') ) AS v("UserName","PasswordHash")
JOIN "User" u ON u."UserName" = v."UserName"
ON CONFLICT ("UserId") DO NOTHING;
